CREATE POLICY "Public read access to obras" ON storage.objects FOR SELECT TO anon, authenticated USING (bucket_id = 'obras');
CREATE POLICY "Admins can upload obras" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'obras' AND public.has_role(auth.uid(), 'admin'));
CREATE POLICY "Admins can update obras" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'obras' AND public.has_role(auth.uid(), 'admin'));
CREATE POLICY "Admins can delete obras" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'obras' AND public.has_role(auth.uid(), 'admin'));